// ============================================================================
// Task 112 — downloadable report artifacts (read-only).
// /api/model-report/download?format=json|csv|md|pdf
// The PDF is pre-generated by scripts/task112_build_report.py (reportlab);
// there is no runtime PDF generation path in the app, so the committed PDF is
// served — guaranteeing the downloaded report matches the versioned artifact.
// ============================================================================
import { NextRequest, NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";
import { gateUser } from "@/lib/latent/access-control";

export const dynamic = "force-dynamic";

const FILES: Record<string, { file: string; type: string }> = {
  json: { file: "model_strategy_performance_latest.json", type: "application/json" },
  csv: { file: "model_strategy_comparison_latest.csv", type: "text/csv" },
  md: { file: "../../docs/reports/psx_model_strategy_performance_report.md", type: "text/markdown" },
  pdf: { file: "psx_model_strategy_performance_report.pdf", type: "application/pdf" },
};

export async function GET(req: NextRequest) {
  const __task121_gate = await gateUser(req, {"permission": "feature.reports_export", "usage": "report_export"});
  if (__task121_gate instanceof Response) return __task121_gate;
  const fmt = req.nextUrl.searchParams.get("format") ?? "json";
  const entry = FILES[fmt];
  if (!entry) {
    return NextResponse.json({ error: "unsupported_format", supported: Object.keys(FILES) }, { status: 400 });
  }
  try {
    const p = path.resolve(path.join(process.cwd(), "data", "reports"), entry.file);
    if (!p.startsWith(path.join(process.cwd(), "data", "reports")) && !p.startsWith(path.join(process.cwd(), "docs"))) {
      throw new Error("path_escape");
    }
    const buf = await fs.readFile(p);
    return new NextResponse(new Uint8Array(buf), {
      headers: {
        "Content-Type": `${entry.type}; charset=utf-8`,
        "Content-Disposition": `attachment; filename="${path.basename(p)}"`,
      },
    });
  } catch {
    return NextResponse.json({ error: "artifact_unavailable", format: fmt, hint: "run scripts/task112_build_report.py" }, { status: 404 });
  }
}
